{"function": "() => {
    const articles = document.querySelectorAll('article article');
    const data = [];
    articles.forEach(article => {
        const yearElem = article.querySelector('[ref*="e"]');
        // year is first generic child text content
        const year = article.firstChild?.textContent?.trim();
        // name is heading level 2
        const nameElem = article.querySelector('h2');
        const name = nameElem ? nameElem.textContent.trim() : null;
        // nationality is generic after heading
        const nationalityElem = article.querySelector('h2 + generic');
        let nationality = nationalityElem ? nationalityElem.textContent.trim() : null;
        if (!nationality) {
            // maybe there is no nationality element
            // try to find any generic that is not year and not heading
            const generics = article.querySelectorAll('generic');
            for (let g of generics) {
                if (g.textContent && g.textContent.trim() && g !== article.firstChild && !g.querySelector('h2')) {
                    nationality = g.textContent.trim();
                    break;
                }
            }
        }
        if (year && name) {
            data.push({year, name, nationality});
        }
    });
    return data;
}"}

